import unittest
from decimal import Decimal
from invoice import total
from formatters import render_total
class Contract(unittest.TestCase):
    def test_tax(self): self.assertEqual(total("100", ".2"), Decimal("120.00"))
    def test_rounding(self): self.assertEqual(total("1.005", 0), Decimal("1.01"))
    def test_format(self): self.assertEqual(render_total(Decimal("10")), "10.00")
    def test_integration(self): self.assertEqual(render_total(total(10, ".1")), "11.00")
    def test_invalid(self):
        with self.assertRaises(ValueError): total(-1, 0)

